#!/usr/bin/env python3
"""Run the unchanged native IP descriptor/hello protocol on the desktop JVM."""
from pathlib import Path
import json,hashlib,subprocess,tempfile
project=Path(__file__).resolve().parents[2];native=project.parent/'Android_WatchRSS/app/src/main/java/com/lightningstudio/watchrss/phoneconnection/ip/IpSyncProtocol.kt';cache=Path.home()/'.gradle/caches/modules-2/files-2.1'
deps=[('org.jetbrains.kotlin','kotlin-compiler-embeddable','2.2.21'),('org.jetbrains.kotlin','kotlin-stdlib','2.2.21'),('org.jetbrains.kotlin','kotlin-script-runtime','2.2.21'),('org.jetbrains.kotlin','kotlin-reflect','1.6.10'),('org.jetbrains.intellij.deps','trove4j','1.0.20200330'),('org.jetbrains.kotlinx','kotlinx-coroutines-core-jvm','1.8.0'),('org.jetbrains','annotations','13.0'),('org.json','json','20240303')]
cp=':'.join(str(next((cache/g/n/v).glob('*/*.jar'))) for g,n,v in deps)
base={'version':2,'serverDeviceId':'手机😀','epoch':7,'expiresAt':2000000000000,'port':39999,'endpoints':[{'endpointId':'b','address':'192.168.1.2','family':'ipv4','transportKind':'wifiLan','priority':300},{'endpointId':'a','address':'192.168.1.3','family':'ipv4','transportKind':'wifiLan','priority':300},{'endpointId':'x','address':'127.0.0.1','transportKind':'bluetoothBridge'}],'challengeId':'challenge','challengeSecret':'AAECAwQFBgcICQoLDA0ODw=='}
cases=[base,{**base,'version':1},{**base,'expiresAt':999},{**base,'port':0},{**base,'port':65536},{**base,'endpoints':[]},{**base,'endpoints':[{'endpointId':'z','address':'192.168.1.2','transportKind':'future'},{'address':'bad'},None,['compact','10.0.0.2','phoneHotspot',250]]},{**base,'endpoints':[{'endpointId':'n','address':'192.168.1.2','transportKind':'wifiLan','priority':4294967297}]},{'v':2,'id':'phone','e':8,'x':2000000000000,'p':40000,'a':[['wifi','10.1.2.3','wifiLan',300]],'c':'short','k':base['challengeSecret']},{**base,'challengeSecret':'not+url/key'},{**base,'challengeSecret':''}]
probe=r'''package com.lightningstudio.watchrss.phoneconnection.ip
fun main(args:Array<String>){val input=org.json.JSONArray(java.io.File(args[0]).readText());val rows=org.json.JSONArray();for(i in 0 until input.length()){val raw=input.getJSONObject(i);val d=IpEndpointDescriptor.fromJson(raw);val row=org.json.JSONObject().put("input",raw).put("canonical",d.canonicalPayload());try{val signed=d.copy(hmac=IpSyncProtocol.hmac(d.challengeSecret,d.canonicalPayload()));row.put("signature",signed.hmac).put("valid",signed.verify(1000)).put("tampered",signed.copy(hmac=signed.hmac+"x").verify(1000));val hello=IpSyncProtocol.buildHello(signed,"watch😀","nonce",if(i%2==0)null else "resume",i.toLong());row.put("hello",hello);val ack=IpHelloAck(d.serverDeviceId,"session",IpTransportKind.WIFI_LAN,i.toLong(),"serverNonce","");val signedAck=ack.copy(hmac=IpSyncProtocol.hmac(d.challengeSecret,ack.canonicalPayload()));row.put("ack",org.json.JSONObject().put("serverDeviceId",signedAck.serverDeviceId).put("sessionId",signedAck.sessionId).put("routeKind",signedAck.routeKind.wireName).put("acceptedResumeSeq",signedAck.acceptedResumeSeq).put("serverNonce",signedAck.serverNonce).put("hmac",signedAck.hmac)).put("ackValid",IpSyncProtocol.verifyAck(signed,signedAck));}catch(e:Exception){row.put("error",e.javaClass.simpleName);};rows.put(row)};println(rows)}'''
with tempfile.TemporaryDirectory(prefix='watchrss-ip-oracle-') as temp:
 p=Path(temp);(p/'Probe.kt').write_text(probe);(p/'input.json').write_text(json.dumps(cases,ensure_ascii=True));subprocess.run(['java','-cp',cp,'org.jetbrains.kotlin.cli.jvm.K2JVMCompiler','-no-stdlib','-no-reflect','-classpath',cp,'-d',temp,str(native),str(p/'Probe.kt')],check=True);rows=json.loads(subprocess.check_output(['java','-cp',temp+':'+cp,'com.lightningstudio.watchrss.phoneconnection.ip.ProbeKt',str(p/'input.json')],text=True))
result={'sourceSha256':hashlib.sha256(native.read_bytes()).hexdigest(),'runtime':'Desktop JVM executing unchanged native IpSyncProtocol.kt','cases':rows};path=project/'tests/fixtures/ip-protocol-native.json';path.write_text(json.dumps(result,ensure_ascii=True,indent=2)+'\n');print('Captured',len(rows),'native cases')
